module Account
  # Communication preferences for customers who aren't necessarily signed in.
  #
  # Customers reach these pages from a link containing a token generated by
  # User#generate_token_for(:communication_preferences), so only the owner of
  # an email address can change its preferences. Signed in customers without
  # a token are sent to their account details instead.
  class CommunicationPreferencesController < ApplicationController
    before_action :set_user, except: :updated

    # Provides options to opt-in or opt-out.
    def index
    end

    # Provides option only to opt-out.
    def unsubscribe
    end

    def update
      @user.update_explicit_opt_in(params[:wanted] == "Yes Please")
      @user.save
      redirect_to action: :updated
    end

    def updated
    end

    private

    def set_user
      @user = User.find_by_token_for(:communication_preferences, params[:token].to_s)
      return if @user

      if logged_in?
        redirect_to account_edit_path
      else
        render :invalid_link, status: :not_found
      end
    end
  end
end
